fn element_wise_divide(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    assert_eq!(arr1.len(), arr2.len(), "input arrays must have equal length");

    let mut result = Vec::with_capacity(arr1.len());
    for i in 0..arr1.len() {
        let divisor = arr2[i];
        assert!(divisor != 0, "arr2 must not contain zero elements");

        // Integer (truncating) division for unsigned integers.
        let q = arr1[i] / divisor;

        // Per problem statement, quotient fits in i32 range; we defensively assert it.
        assert!(q <= i32::MAX as u32, "quotient does not fit in i32 range");

        result.push(q);
    }
    result
}